-- Phase 3 baseline. Apply with your PostgreSQL migration runner (or Alembic).
-- JSON columns intentionally preserve current Flutter payloads for forward compatibility.
create table if not exists users (id varchar(36) primary key, auth_subject varchar(255) unique not null, email varchar(320), display_name varchar(255), plan varchar(50) not null default 'free', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists creator_profiles (id varchar(36) primary key, user_id varchar(36) unique not null references users(id) on delete cascade, data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists generations (id varchar(36) primary key, user_id varchar(36) not null references users(id) on delete cascade, platform varchar(50) not null, content_type varchar(50) not null, idea text not null, response jsonb not null, retry_count integer not null default 0, created_at timestamptz not null default now());
create table if not exists campaigns (id varchar(36) primary key, user_id varchar(36) not null references users(id) on delete cascade, goal text not null, platform varchar(50) not null default 'All', duration_days integer not null, plan jsonb not null, created_at timestamptz not null default now());
create table if not exists usage_logs (id varchar(36) primary key, user_id varchar(36) not null references users(id) on delete cascade, event_type varchar(80) not null, quantity integer not null default 1, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists ix_usage_user_event_time on usage_logs(user_id, event_type, created_at);
